// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IPair{function spot() external view returns(uint);} contract SpotOracleConsumer {IPair public pair; constructor(IPair p){pair=p;} function value(uint amount) external view returns(uint){return amount*pair.spot()/1e18;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ITwap{function consult(uint32 window) external view returns(uint);} contract TwapConsumer {ITwap public oracle; constructor(ITwap o){oracle=o;} function value(uint amount) external view returns(uint){return amount*oracle.consult(1800)/1e18;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract DonationShares {uint public totalShares; mapping(address=>uint) public shares; function deposit() external payable {uint minted=totalShares==0?msg.value:msg.value*totalShares/address(this).balance;shares[msg.sender]+=minted;totalShares+=minted;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PreBalanceShares {uint public totalShares;mapping(address=>uint) public shares;function deposit() external payable {uint beforeBal=address(this).balance-msg.value;uint minted=totalShares==0?msg.value:msg.value*totalShares/beforeBal;require(minted>0);shares[msg.sender]+=minted;totalShares+=minted;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract RoundingLoss {uint public rate=1e30; mapping(address=>uint) public credit; function deposit(uint amount) external {credit[msg.sender]+=amount*1e18/rate;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract RoundingGuard {uint public rate=1e30;mapping(address=>uint) public credit;function deposit(uint amount) external {uint c=amount*1e18/rate;require(c>0);credit[msg.sender]+=c;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract OpenMint {mapping(address=>uint) public balance;function mint(address to,uint amount) external {balance[to]+=amount;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract RoleMint {mapping(address=>uint) public balance;mapping(address=>bool) public minter;address public owner;constructor(){owner=msg.sender;}function setMinter(address a,bool v) external {require(msg.sender==owner);minter[a]=v;}function mint(address to,uint amount) external {require(minter[msg.sender]);balance[to]+=amount;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract UnboundedLoop {address[] public users;function add(address a) external {users.push(a);}function pay() external payable {for(uint i=0;i<users.length;i++){payable(users[i]).transfer(1);}} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PagedLoop {address[] public users;function add(address a) external {users.push(a);}function slice(uint start,uint count) external view returns(address[] memory out){uint end=start+count;if(end>users.length)end=users.length;out=new address[](end-start);for(uint i=start;i<end;i++)out[i-start]=users[i];} }
